// Gestión académica (35) connected to the session and to Expo Router: the admin shell's "academic" tab
// (whole institution) and the area admin shell's only tab (its areas).
import { useRouter, type Href } from 'expo-router';
import { useMemo } from 'react';
import { useSession } from '../auth/session';
import { AcademicScreen } from './AcademicScreen';
import { academicInstitutionFor, bindAcademicApi, createAccessRunner } from './academicClient';

// Typed routes (.expo/types) are generated by `expo start`; this path exists under src/app/(app).
const ADMIN_USERS = '/admin/users' as Href;

const ROLE_LABELS = { institution_admin: 'Administrador', area_admin: 'Administrador de área' } as const;

export function AcademicRoute({ role }: { role: 'institution_admin' | 'area_admin' }) {
  const { user, activeInstitutionId } = useSession();
  const router = useRouter();
  const run = useMemo(() => createAccessRunner(), []);
  const institutionId = user ? academicInstitutionFor(user.memberships, activeInstitutionId, role) : null;
  const client = useMemo(
    () => (institutionId === null ? null : bindAcademicApi(run, institutionId)),
    [run, institutionId],
  );
  if (!client) return null;
  return (
    <AcademicScreen
      key={institutionId}
      client={client}
      roleLabel={ROLE_LABELS[role]}
      onOpenUsers={role === 'institution_admin' ? () => router.push(ADMIN_USERS) : undefined}
    />
  );
}
